import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"FD Cal — engineering audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/README.html"}],["meta",{"property":"og:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/README.html"}],["meta",{"name":"twitter:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/README.md","filePath":"audits/README.md","lastUpdated":1794198491000}`),a={name:`audits/README.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="fd-cal-—-engineering-audit" tabindex="-1">FD Cal — engineering audit <a class="header-anchor" href="#fd-cal-—-engineering-audit" aria-label="Permalink to “FD Cal — engineering audit”">​</a></h1><p><strong>Re-audit date:</strong> 9 November 2026<br><strong>Audited source:</strong> <code>dev</code> at <code>caccaf26b4415ae783959e888ff45e33becdadf6</code> (tree <code>8044397ede661a22c0014bb646b09df0abcc2e77</code>)<br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">aaron-fredrick/RULESETS</a> <code>main</code> at <code>79d7dd4f0c0d544ba85abeb19286ef2cae34bf89</code><br><strong>Status:</strong> Static RULESETS re-audit of the active <code>dev</code> codebase after PRs <a href="https://github.com/aaron-fredrick/FD-Calculator/pull/75" target="_blank" rel="noreferrer">#75</a> and <a href="https://github.com/aaron-fredrick/FD-Calculator/pull/80" target="_blank" rel="noreferrer">#80</a>. The deployment scope for this pass is <code>dev</code>; <code>main</code> integration is explicitly deferred. Findings and remaining work are tracked below.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to “Reports”">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Coverage</th></tr></thead><tbody><tr><td><a href="./EXECUTIVE-SUMMARY.html">Executive summary</a></td><td>Priority-ranked findings, owner dispositions and remediation order</td></tr><tr><td><a href="./IMPLEMENTATION-PLAN.html">Implementation plan</a></td><td>Detailed analysis, implementation phases, acceptance criteria and non-regression guardrails</td></tr><tr><td><a href="./ENGINE-CORE.html">Engine and financial core</a></td><td>Dates, interest, FD cash flows, simulation lifecycle, balances and results</td></tr><tr><td><a href="./STRATEGIES-AND-SEARCH.html">Strategies and search</a></td><td>Greedy, GSS, Absolute R, Absolute R+, search budgets, parity and architecture</td></tr><tr><td><a href="./WEB-UI-UX-ACCESSIBILITY.html">Web UI, UX and accessibility</a></td><td>Form flows, responsive layout, motion, keyboard and screen-reader semantics</td></tr><tr><td><a href="./REPORTING-OUTPUTS.html">Reporting and outputs</a></td><td>In-app metrics, standalone HTML, ledger, charts and financial presentation</td></tr><tr><td><a href="./DATA-AND-FINANCIAL-ASSUMPTIONS.html">Data and financial assumptions</a></td><td>Catalogue quality, provenance, eligibility, fees, AIT and product constraints</td></tr><tr><td><a href="./SECURITY-PRIVACY.html">Security and privacy</a></td><td>Untrusted configuration, DOM rendering, local storage and client-side exposure</td></tr><tr><td><a href="./BUILD-DEPLOYMENT-AND-QUALITY.html">Build, deployment and quality</a></td><td>GitHub Actions, Pages composition, dev preview, tests and operational gaps</td></tr></tbody></table><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to “Method”">​</a></h2><p>The review applies the principles in the RULESETS repository, principally:</p><ul><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Coding" target="_blank" rel="noreferrer">Coding practices</a>: maintainability, modularity, API contracts, error handling, security boundaries, documentation and meaningful tests.</li><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/UI" target="_blank" rel="noreferrer">UI guidelines</a>: product-aware design, hierarchy, restraint, interaction, motion, responsive behaviour and rendered-state QA.</li><li><a href="https://github.com/aaron-fredrick/RULESETS/tree/main/Web" target="_blank" rel="noreferrer">Web engineering practices</a>: production standards, privacy, analytics, SEO, accessibility, performance and release readiness.</li></ul><p>This is a risk-based source audit against all applicable Coding, UI and Web ruleset documents, covering the active JavaScript engine, strategy/search paths, browser UI, reporting, catalogue/configuration paths, CLI, build scripts, Pages workflows, crawler metadata and test inventory. It is not a line-by-line proof of every statement. It is not a formal verification, financial-product certification, penetration test, legal opinion, or complete external revalidation of every bank rate and fee. Browser screenshots, assistive-technology checks and live production/dev visual inspection remain separate verification tasks.</p><h2 id="current-finding-status" tabindex="-1">Current finding status <a class="header-anchor" href="#current-finding-status" aria-label="Permalink to “Current finding status”">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Findings</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Completed</strong></td><td>SEC-01, FIN-01, FIN-02, ENG-05, DEPLOY-01</td><td>Implemented on <code>dev</code>; applicable regression/contract coverage is present.</td></tr><tr><td><strong>Implemented on this branch</strong></td><td>UI-01, UI-02, UI-03, DATA-01, DATA-04, FIN-03, PRIV-01</td><td>Accessible interaction fixes, strict CSV parsing, product-level provenance and local draft deletion are implemented with regression coverage; pending shipment to <code>dev</code>.</td></tr><tr><td><strong>Implemented; follow-up gate</strong></td><td>SEARCH-01</td><td>Core behaviour and tests are in place; benchmark calibration remains.</td></tr><tr><td><strong>Partial</strong></td><td>ENG-01, ENG-02, DATA-06</td><td>Part of the requirement is delivered; a specific contract or source gap remains.</td></tr><tr><td><strong>Open</strong></td><td>ENG-03/04, DATA-05, SEARCH-02/03, WEB-SEC-02, QA-REP-01</td><td>Not yet resolved.</td></tr><tr><td><strong>Scope closed</strong></td><td>DATA-02</td><td>Owner-confirmed product scope; no eligibility-verification feature planned.</td></tr><tr><td><strong>Deferred</strong></td><td>DATA-03, QA-01</td><td>Requires a separate owner decision.</td></tr></tbody></table><h2 id="severity" tabindex="-1">Severity <a class="header-anchor" href="#severity" aria-label="Permalink to “Severity”">​</a></h2><ul><li><strong>P1 — High:</strong> credible security exposure or materially misleading financial output. Address before broad use.</li><li><strong>P2 — Medium:</strong> correctness, runtime, data-trust or deployment risk with meaningful user impact.</li><li><strong>P3 — Low:</strong> accessibility, maintainability, observability or test-quality improvement; schedule after higher-risk work.</li></ul><p>Each finding includes evidence, impact, and a concrete recommendation. A finding marked <em>assumption to confirm</em> should be resolved against bank/product terms before changing the model.</p><h2 id="verification-boundary" tabindex="-1">Verification boundary <a class="header-anchor" href="#verification-boundary" aria-label="Permalink to “Verification boundary”">​</a></h2><p>The source reviewed is <code>dev</code> commit <code>caccaf26b4415ae783959e888ff45e33becdadf6</code>. On the exact reviewed <code>dev</code> commit, the Node.js test/syntax workflow passed (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842534" target="_blank" rel="noreferrer">42553842534</a>) and the independent dev web build/publish passed (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842533" target="_blank" rel="noreferrer">42553842533</a>). The dev documentation/benchmark publishing workflow was still in progress when checked (<a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42553842591" target="_blank" rel="noreferrer">42553842591</a>). No browser automation was executed as part of this static re-audit. Static inspection does not verify screen-reader output, real-device layout, bank-product terms, or HTTP response behaviour.</p><h2 id="planning-status" tabindex="-1">Planning status <a class="header-anchor" href="#planning-status" aria-label="Permalink to “Planning status”">​</a></h2><p>See the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a> for phase-level status. <strong>Completed on <code>dev</code>:</strong> SEC-01, FIN-01, FIN-02, ENG-05 and DEPLOY-01. <strong>Implemented with follow-up gate:</strong> SEARCH-01. <strong>Partial:</strong> ENG-01, ENG-02 and DATA-06. <strong>Open:</strong> DATA-05, WEB-SEC-02 and the remaining subsystem findings. <strong>Implemented on this branch, pending dev shipment:</strong> UI-01, UI-02, UI-03, DATA-01, DATA-04, FIN-03 and PRIV-01. <strong>Closed as scope decision:</strong> DATA-02. <strong>Deferred:</strong> DATA-03, QA-01 and any <code>main</code>-branch deployment integration.</p><p>PR #75 delivered the core security, result-semantics, bounded-search and catalogue-disclosure work. PR #80 split dev web/docs publishing and added dev-side assembly. The remaining code work should proceed in focused branches from the current <code>dev</code> baseline; this branch is being retained for the audit and plan.</p><h2 id="crawler-and-release-path-policy" tabindex="-1">Crawler and release-path policy <a class="header-anchor" href="#crawler-and-release-path-policy" aria-label="Permalink to “Crawler and release-path policy”">​</a></h2><p>The <code>/dev/</code> subtree is a public preview for review, not an indexable production destination. The production root <code>robots.txt</code> must disallow <code>/FD-Calculator/dev/</code>; every generated dev HTML entry point must carry <code>noindex,nofollow</code>; and the production sitemap must contain only canonical production URLs, never preview URLs. <code>robots.txt</code> is crawler guidance, not access control. The production docs build merges the canonical site root and <code>/web/</code> application URL into the documentation sitemap and publishes the assembled sitemap at the site root. Preview builds omit sitemap output, while dev HTML is marked <code>noindex,nofollow</code>; this is a verified positive control, not an open finding.</p>`,20)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};